const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
export function createGame(seed=Date.now(),classId='archer'){
 let s=seed>>>0;const random=()=>{s=(s+0x6D2B79F5)|0;let t=Math.imul(s^s>>>15,1|s);t^=t+Math.imul(t^t>>>7,61|t);return((t^t>>>14)>>>0)/4294967296};
 const hero=classes.find(c=>c.id===classId)||classes[0];
 const stats={damage:24,interval:.65,speed:190,maxHealth:100,regen:0,shots:1,pierce:0,orbits:0,nova:0,armor:1,xp:1,range:320,projectileSpeed:450,radius:80,crit:.05,critPower:2,leech:0,evade:0,thorns:0,cleave:0,quake:0,knockback:0,berserk:0,execution:0,retaliation:0,shieldMax:0,recovery:0,burn:0,fireaura:0,fireball:0,explode:0,frost:0,icelance:0,chain:0,thunder:0,venom:0,roots:0,crossbow:0,elemental:1,flatPower:1,petPower:1,petHaste:1,...hero.stats};
 return{random,classId:hero.id,status:'ready',time:0,x:0,y:0,facing:1,health:stats.maxHealth,shield:0,level:1,xp:0,nextXP:9,kills:0,bossKills:0,miniKills:0,wave:1,nextBoss:120,nextMini:45,bossIndex:0,miniIndex:0,enemies:[],bullets:[],enemyBullets:[],hazards:[],pets:[],effects:[],numbers:[],build:{},choices:[],stats,attack:0,spawn:0,invulnerable:0,slow:0,lastDamage:-10,id:0,targetId:null,clocks:{},deathQueue:[],announcement:'',announcementLife:0};
}
export function rollChoices(g){const pool=talents.filter(t=>!(t.id==='critical'&&g.stats.crit>=.75)&&(!t.max||(g.build[t.id]||0)<t.max)&&(!t.classes||t.classes.includes(g.classId)));const picks=[];if(g.level===2){const pets=pool.filter(t=>['wolf','stormpet','frostpet','firepet'].includes(t.id));picks.push(pets[Math.floor(g.random()*pets.length)].id)}while(picks.length<3&&pool.length){const i=Math.floor(g.random()*pool.length),t=pool.splice(i,1)[0];if(!picks.includes(t.id))picks.push(t.id)}return picks}
export function chooseUpgrade(g,id){if(g.status!=='levelup'||!g.choices.includes(id))return false;const t=talents.find(t=>t.id===id);t.apply(g);g.build[id]=(g.build[id]||0)+1;g.choices=[];g.status='playing';checkLevel(g);return true}
function checkLevel(g){if(g.xp>=g.nextXP){g.xp-=g.nextXP;g.level++;g.nextXP=Math.round(g.nextXP*1.16+5);g.health=Math.min(g.stats.maxHealth,g.health+g.stats.recovery);g.status='levelup';g.choices=rollChoices(g)}}
export function summonPet(g,kind){const pet={id:++g.id,kind,x:g.x+30,y:g.y+30,cooldown:.1,targetId:null};g.pets.push(pet);return pet}
export function constrain(entity,r=14){entity.x=clamp(entity.x,MAP.left+r,MAP.right-r);entity.y=clamp(entity.y,MAP.top+r,MAP.bottom-r);for(const o of MAP.obstacles){let dx=entity.x-o.x,dy=entity.y-o.y,d=Math.hypot(dx,dy);if(d<r+o.r){if(d<.001){dx=1;dy=0;d=1}entity.x=o.x+dx/d*(r+o.r);entity.y=o.y+dy/d*(r+o.r)}}}
export function spawnEnemy(g,kind,position){if(kind===true)kind=['warden','frostking','dragon'][g.bossIndex++%3];if(!kind){const pool=['walker','walker'];if(g.time>20)pool.push('bat');if(g.time>35)pool.push('ranger');if(g.time>50)pool.push('brute','charger');if(g.time>70)pool.push('spitter');if(g.time>95)pool.push('shaman','wraith');kind=pool[Math.floor(g.random()*pool.length)]}const def=monsters[kind]||monsters.walker;if(!monsters[kind])kind='walker';let x,y;if(position){({x,y}=position)}else{let chosen;for(let i=0;i<24;i++){const a=g.random()*Math.PI*2,r=570+g.random()*150;chosen={x:clamp(g.x+Math.cos(a)*r,MAP.left+45,MAP.right-45),y:clamp(g.y+Math.sin(a)*r,MAP.top+45,MAP.bottom-45)};if(distance(chosen,g)>400)break}({x,y}=chosen)}const hp=def.hp*(1+g.time/230);const e={...def,id:++g.id,kind,x,y,hp,maxHP:hp,speed:def.speed*(1+Math.min(g.time/1500,.6)),hit:0,slow:0,freeze:0,stun:0,burn:0,poison:0,burnPower:0,poisonPower:0,orbitHit:0,cooldown:1+g.random(),special:3+g.random()*2,telegraph:0,dash:0,dx:0,dy:0};constrain(e,e.r);g.enemies.push(e);return e}
function fx(g,kind,x,y,r,color,life=.4,extra={}){if(g.effects.length<180)g.effects.push({kind,x,y,r,color,life,max:life,...extra})}
function number(g,x,y,text,color='#f5e6b3'){if(g.numbers.length<55)g.numbers.push({x,y,text,life:.7,color})}
function damageHero(g,amount,source){if(g.status!=='playing'||g.invulnerable>0)return false;if(g.random()<g.stats.evade){number(g,g.x,g.y-25,'EVADE','#b6dfd0');g.invulnerable=.2;return false}let damage=amount*g.stats.armor,absorbed=Math.min(g.shield,damage);g.shield-=absorbed;damage-=absorbed;g.health-=damage;g.lastDamage=g.time;g.invulnerable=.5;fx(g,'hit',g.x,g.y,35,'#f79280',.25);if(source&&g.stats.thorns)hurtEnemy(g,source,g.stats.thorns*g.stats.flatPower,{direct:false});if(g.stats.retaliation&&tick(g,'retaliation',2,0)){area(g,g.x,g.y,140,g.stats.damage*g.stats.retaliation,{direct:false},'#a7d7d1')}return true}
export function hurtEnemy(g,e,amount,opts={}){if(e.hp<=0)return;let damage=amount*(1-(e.armor||0));if(opts.direct!==false){if(g.random()<g.stats.crit)damage*=g.stats.critPower;if(g.health<g.stats.maxHealth*.5)damage*=1+g.stats.berserk;if(e.hp<e.maxHP*.3)damage*=1+g.stats.execution;if(g.stats.burn){e.burn=3;e.burnPower=Math.max(e.burnPower,5*g.stats.burn*g.stats.elemental*g.stats.flatPower)}if(g.stats.venom){e.poison=4;e.poisonPower=Math.max(e.poisonPower,4*g.stats.venom*g.stats.flatPower)}if(g.stats.frost)e.slow=Math.max(e.slow,2+(g.stats.frost-1)*.3);if(g.stats.knockback){const d=distance(e,g)||1,push=g.stats.knockback*((e.boss||e.mini)? .2:1);e.x+=(e.x-g.x)/d*push;e.y+=(e.y-g.y)/d*push;constrain(e,e.r)}}if(opts.freeze)e.freeze=Math.max(e.freeze,opts.freeze*(e.boss?.25:1));if(opts.slow)e.slow=Math.max(e.slow,opts.slow);if(opts.stun)e.stun=Math.max(e.stun,opts.stun*(e.boss?.25:1));if(opts.burn){e.burn=3;e.burnPower=Math.max(e.burnPower,opts.burn)}e.hp-=damage;e.hit=.1;if(opts.direct!==false)number(g,e.x,e.y-15,Math.round(damage),opts.color);if(e.hp<=0){g.kills++;g.bossKills+=e.boss?1:0;g.miniKills+=e.mini?1:0;g.xp+=e.xp*g.stats.xp;g.health=Math.min(g.stats.maxHealth,g.health+g.stats.leech);fx(g,'kill',e.x,e.y,e.r,e.color,.35);if(e.boss||e.mini){g.announcement=`${e.name} defeated · +${Math.round(e.xp*g.stats.xp)} XP`;g.announcementLife=4}if(g.stats.explode)g.deathQueue.push({x:e.x,y:e.y,damage:15*g.stats.explode*g.stats.elemental*g.stats.flatPower})}}
function area(g,x,y,r,damage,opts={},color='#ecc18a'){fx(g,'ring',x,y,r,color,.45);for(const e of g.enemies)if(e.hp>0&&Math.hypot(e.x-x,e.y-y)<r+e.r)hurtEnemy(g,e,damage,opts)}
function nearest(g,origin,range=Infinity,exclude=null){let target=null,best=range;for(const e of g.enemies){if(e.hp<=0||e.id===exclude)continue;const d=distance(e,origin);if(d<best){best=d;target=e}}return target}
function shoot(g,origin,target,damage,kind='arrow',extra={}){const a=Math.atan2(target.y-origin.y,target.x-origin.x)+(extra.angle||0);g.bullets.push({x:origin.x,y:origin.y,vx:Math.cos(a)*(extra.speed||450),vy:Math.sin(a)*(extra.speed||450),life:2.1,damage,kind,left:extra.pierce===undefined?1:extra.pierce+1,hits:new Set(),...extra})}
function lightning(g,origin,first,damage,jumps=3){let target=first,from=origin,used=new Set();for(let i=0;target&&i<jumps;i++){used.add(target.id);fx(g,'lightning',from.x,from.y,0,'#f1dc81',.23,{tx:target.x,ty:target.y});hurtEnemy(g,target,damage,{color:'#f4df8b'});from=target;let closest=null,best=180;for(const e of g.enemies){const d=distance(e,from);if(e.hp>0&&!used.has(e.id)&&d<best){closest=e;best=d}}target=closest}}
function tick(g,key,period,dt){g.clocks[key]=(g.clocks[key]??0)-dt;if(g.clocks[key]<=0){g.clocks[key]=period;return true}return false}
function hazard(g,x,y,r,damage,color,delay=.9,duration=.4,slow=false){g.hazards.push({x,y,r,damage,color,delay,life:duration,max:duration,slow,enemy:true})}
function hostileShot(g,e,angle,kind='arrow',speed=190){if(g.enemyBullets.length>=220)return;g.enemyBullets.push({x:e.x,y:e.y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:kind==='poison'?Math.min(4,distance(e,g)/speed):4,damage:e.damage,kind,r:kind==='poison'?8:6,color:kind==='ice'?'#9bdff4':kind==='fire'?'#ff9d72':kind==='poison'?'#b1cf7d':'#e0bc8b'})}
function summonFoes(g,e,kind,count){for(let i=0;i<count&&g.enemies.length<400;i++){const a=i/count*Math.PI*2;spawnEnemy(g,kind,{x:e.x+Math.cos(a)*60,y:e.y+Math.sin(a)*60})}}
function updateEnemy(g,e,dt){e.hit=Math.max(0,e.hit-dt);e.slow=Math.max(0,e.slow-dt);e.freeze=Math.max(0,e.freeze-dt);e.stun=Math.max(0,e.stun-dt);e.orbitHit=Math.max(0,e.orbitHit-dt);if(e.burn>0){e.burn-=dt;hurtEnemy(g,e,e.burnPower*dt,{direct:false})}if(e.poison>0){e.poison-=dt;hurtEnemy(g,e,e.poisonPower*dt,{direct:false})}if(e.hp<=0)return;e.cooldown-=dt;e.special-=dt;const dx=g.x-e.x,dy=g.y-e.y,d=Math.hypot(dx,dy)||1,angle=Math.atan2(dy,dx);if(e.freeze>0||e.stun>0)return;
 let movement=1;if(['ranger','spitter','summoner','hexer','frostking'].includes(e.behavior))movement=d<200?-1:d<290?0:1;
 if(e.telegraph>0){e.telegraph-=dt;movement=0;if(e.telegraph<=0){e.dash=.65;fx(g,'dash',e.x,e.y,50,e.color,.4)}}
 if(e.dash>0){e.dash-=dt;e.x+=e.dx*430*dt;e.y+=e.dy*430*dt}else{const speed=e.speed*(e.slow>0?.65:1)*(e.behavior==='wraith'&&Math.sin(g.time*1.7+e.id)>0?1.65:1);e.x+=dx/d*speed*movement*dt;e.y+=dy/d*speed*movement*dt}
 constrain(e,e.r);if(d<e.r+16)damageHero(g,e.damage,e);
 if(e.cooldown<=0&&d<580){switch(e.behavior){case'ranger':hostileShot(g,e,angle);e.cooldown=2.8;break;case'spitter':hostileShot(g,e,angle,'poison',145);e.cooldown=3.5;break;case'summoner':summonFoes(g,e,'walker',2);e.cooldown=7;break;case'broodmother':summonFoes(g,e,'bat',3);hostileShot(g,e,angle,'poison',160);e.cooldown=4.5;break;case'hexer':hazard(g,g.x,g.y,78,e.damage,'#bd95de',1.1,3);e.cooldown=3.5;break;case'warden':hazard(g,e.x,e.y,195,e.damage*1.3,'#e5be84',1.15,.45);e.cooldown=4.5;break;case'frostking':for(let i=0;i<12;i++)hostileShot(g,e,i/12*Math.PI*2+g.time*.2,'ice',155);e.cooldown=3.3;break;case'dragon':for(let i=-2;i<=2;i++)hostileShot(g,e,angle+i*.2,'fire',180);e.cooldown=2.5;break}}
 if(e.special<=0){if(['charger','ravager','warden'].includes(e.behavior)&&d<650){e.dx=dx/d;e.dy=dy/d;e.telegraph=e.behavior==='charger'?.8:1.1;e.special=e.behavior==='ravager'?3.5:6}else if(e.behavior==='frostking'){hazard(g,g.x,g.y,100,e.damage,'#8ed5f1',1.1,4,true);e.special=7}else if(e.behavior==='dragon'){for(let i=0;i<3;i++)hazard(g,g.x+(i-1)*105,g.y+Math.sin(i)*70,80,e.damage*.8,'#e99965',1,4);e.special=7}else e.special=4}
}
function updatePets(g,dt){for(let i=0;i<g.pets.length;i++){const p=g.pets[i];p.cooldown-=dt;let target=g.enemies.find(e=>e.id===p.targetId&&e.hp>0&&distance(e,g)<650);if(!target){target=nearest(g,p,600,g.targetId)||nearest(g,p,600);p.targetId=target?.id??null}const melee=p.kind==='wolf';const a=i/Math.max(1,g.pets.length)*Math.PI*2+g.time*.25;let aim=melee&&target?target:{x:g.x+Math.cos(a)*65,y:g.y+Math.sin(a)*65};if(distance(p,g)>650)aim=g;const d=distance(p,aim)||1;if(d>5){const speed=melee?280:240;p.x+=(aim.x-p.x)/d*Math.min(d,speed*dt);p.y+=(aim.y-p.y)/d*Math.min(d,speed*dt)}constrain(p,8);if(!target||p.cooldown>0)continue;const damage=g.stats.damage*g.stats.petPower*(p.kind==='wolf'?1:g.stats.elemental);if(melee&&distance(p,target)<target.r+25){hurtEnemy(g,target,damage*.7,{color:'#c4dca4'});fx(g,'slash',p.x,p.y,35,'#c2d8ad',.2);p.cooldown=.7*g.stats.petHaste}else if(!melee&&distance(p,target)<550){if(p.kind==='stormpet'){lightning(g,p,target,damage*.65,3);p.cooldown=2*g.stats.petHaste}else if(p.kind==='frostpet'){shoot(g,p,target,damage*.65,'ice',{freeze:1.2,color:'#91d7f4'});p.cooldown=1.3*g.stats.petHaste}else{shoot(g,p,target,damage*.8,'fire',{splash:65,burn:7*g.stats.petPower*g.stats.flatPower*g.stats.elemental,color:'#ffac7e'});p.cooldown=1.8*g.stats.petHaste}}}}
function updateAbilities(g,dt){const s=g.stats;for(let i=0;i<s.orbits;i++){const a=g.time*2.5+i*Math.PI*2/s.orbits,x=g.x+Math.cos(a)*s.radius,y=g.y+Math.sin(a)*s.radius;for(const e of g.enemies)if(e.hp>0&&e.orbitHit<=0&&Math.hypot(e.x-x,e.y-y)<e.r+12){e.orbitHit=.35;hurtEnemy(g,e,s.damage*.7)}}
 if(s.cleave&&tick(g,'cleave',1.7,dt))area(g,g.x,g.y,110,s.damage*(.6+.35*s.cleave),{},'#eac28f');
 if(s.quake&&tick(g,'quake',4,dt))area(g,g.x,g.y,135,s.damage*(.7+.35*s.quake),{stun:.7},'#d7c89b');
 if(s.fireaura&&tick(g,'fireaura',1,dt))area(g,g.x,g.y,105,8*s.fireaura*s.elemental*s.flatPower,{direct:false,burn:4*s.fireaura*s.flatPower*s.elemental},'#ed9870');
 if(s.nova&&tick(g,'nova',6,dt))area(g,g.x,g.y,170,s.damage*(.7+.25*s.nova)*s.elemental,{freeze:1.5+s.nova*.2},'#91d7f4');
 if(s.roots&&tick(g,'roots',5,dt))area(g,g.x,g.y,160,12*s.roots*s.flatPower,{stun:1+s.roots*.25},'#a8cf87');
 const target=nearest(g,g,500);if(target){if(s.chain&&tick(g,'chain',3,dt))lightning(g,g,target,s.damage*.8*s.elemental,2+s.chain);if(s.thunder&&tick(g,'thunder',5,dt)){area(g,target.x,target.y,100,s.damage*s.thunder*s.elemental,{stun:.8},'#f1dc81');fx(g,'lightning',target.x,target.y-200,0,'#f1dc81',.3,{tx:target.x,ty:target.y})}if(s.crossbow&&tick(g,'crossbow',1.4,dt))shoot(g,g,target,s.damage*(.5+s.crossbow*.3),'arrow');if(s.fireball&&tick(g,'fireball',3,dt))shoot(g,g,target,s.damage*(.7+s.fireball*.3)*s.elemental,'fire',{splash:85,burn:6*s.fireball*s.flatPower*s.elemental});if(s.icelance&&tick(g,'icelance',2.2,dt))shoot(g,g,target,s.damage*(.5+s.icelance*.3)*s.elemental,'ice',{pierce:3,freeze:1})}}
function segmentDistance(x,y,ax,ay,bx,by){const dx=bx-ax,dy=by-ay,t=clamp(((x-ax)*dx+(y-ay)*dy)/(dx*dx+dy*dy||1),0,1);return Math.hypot(x-ax-t*dx,y-ay-t*dy)}
export function step(g,dt,input={x:0,y:0}){if(g.status!=='playing'||!Number.isFinite(dt)||dt<=0)return;dt=Math.min(dt,.05);g.time+=dt;if(g.clocks.retaliation>0)g.clocks.retaliation-=dt;g.wave=1+Math.floor(g.time/30);g.announcementLife=Math.max(0,g.announcementLife-dt);g.invulnerable=Math.max(0,g.invulnerable-dt);g.slow=Math.max(0,g.slow-dt);g.health=Math.min(g.stats.maxHealth,g.health+g.stats.regen*dt);if(g.time-g.lastDamage>5)g.shield=Math.min(g.stats.shieldMax,g.shield+8*dt);
 let mx=Number.isFinite(input.x)?input.x:0,my=Number.isFinite(input.y)?input.y:0,len=Math.hypot(mx,my);if(len>1){mx/=len;my/=len}const speed=g.stats.speed*(g.slow>0?.65:1);g.x+=mx*speed*dt;g.y+=my*speed*dt;constrain(g,18);if(mx)g.facing=mx>0?1:-1;
 const rate=.7+g.time*.016+g.wave*.05;g.spawn+=dt*rate;while(g.spawn>=1){g.spawn--;if(g.enemies.length<380)spawnEnemy(g)}if(g.time+1e-7>=g.nextMini){const e=spawnEnemy(g,['ravager','broodmother','hexer'][g.miniIndex++%3]);g.nextMini+=45;g.announcement=`MINIBOSS · ${e.name}`;g.announcementLife=4}if(g.time+1e-7>=g.nextBoss){const e=spawnEnemy(g,['warden','frostking','dragon'][g.bossIndex++%3]);g.nextBoss+=120;g.announcement=`BOSS · ${e.name}`;g.announcementLife=5}
 const grid=new Map(),cell=80;for(const e of [...g.enemies]){updateEnemy(g,e,dt);if(e.hp<=0)continue;const k=`${Math.floor(e.x/cell)},${Math.floor(e.y/cell)}`;if(!grid.has(k))grid.set(k,[]);grid.get(k).push(e)}
 g.attack-=dt;const target=nearest(g,g,g.stats.range);g.targetId=target?.id??null;if(target&&g.attack<=0){g.attack=Math.max(.09,g.stats.interval);if(g.classId==='fighter'||g.classId==='assassin'){const radius=g.stats.range;area(g,g.x,g.y,radius,g.stats.damage,{},classes.find(c=>c.id===g.classId).color);fx(g,'slash',g.x,g.y,radius,'#efc99a',.22)}else{for(let i=0;i<g.stats.shots;i++)shoot(g,g,target,g.stats.damage*(g.classId==='mage'?g.stats.elemental:1),g.classId==='mage'?'fire':'arrow',{angle:(i-(g.stats.shots-1)/2)*.14,pierce:g.stats.pierce,splash:g.classId==='mage'?58:0,burn:g.classId==='mage'?5:0})}}
 updatePets(g,dt);updateAbilities(g,dt);
 for(const b of g.bullets){const ax=b.x,ay=b.y;b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;const minX=Math.floor((Math.min(ax,b.x)-45)/cell),maxX=Math.floor((Math.max(ax,b.x)+45)/cell),minY=Math.floor((Math.min(ay,b.y)-45)/cell),maxY=Math.floor((Math.max(ay,b.y)+45)/cell);for(let cx=minX;cx<=maxX;cx++)for(let cy=minY;cy<=maxY;cy++)for(const e of grid.get(`${cx},${cy}`)||[]){if(b.left<=0||e.hp<=0||b.hits.has(e.id))continue;if(segmentDistance(e.x,e.y,ax,ay,b.x,b.y)<e.r+5){b.hits.add(e.id);b.left--;hurtEnemy(g,e,b.damage,{freeze:b.freeze,burn:b.burn,color:b.color});if(b.splash)area(g,e.x,e.y,b.splash,b.damage*.55,{direct:false,burn:b.burn},'#f2a079')}}}g.bullets=g.bullets.filter(b=>b.life>0&&b.left>0);
 for(const b of g.enemyBullets){const ax=b.x,ay=b.y;b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(segmentDistance(g.x,g.y,ax,ay,b.x,b.y)<b.r+15){if(damageHero(g,b.damage)&&b.kind==='ice')g.slow=2;b.life=0}if(b.kind==='poison'&&b.life<=0)hazard(g,b.x,b.y,48,b.damage,'#a7cf73',0,3)}g.enemyBullets=g.enemyBullets.filter(b=>b.life>0&&b.x>MAP.left-50&&b.x<MAP.right+50&&b.y>MAP.top-50&&b.y<MAP.bottom+50);
 for(const h of g.hazards){if(h.delay>0){h.delay-=dt;continue}h.life-=dt;if(Math.hypot(g.x-h.x,g.y-h.y)<h.r+12){if(damageHero(g,h.damage)&&h.slow)g.slow=2}}g.hazards=g.hazards.filter(h=>h.life>0);
 // Queue death bursts instead of recursive calls so large chains cannot overflow the stack.
 for(let n=0;g.deathQueue.length&&n<400;n++){const p=g.deathQueue.shift();area(g,p.x,p.y,75,p.damage,{direct:false},'#e9a27b')}if(g.deathQueue.length>400)g.deathQueue.length=400;
 g.enemies=g.enemies.filter(e=>e.hp>0);for(const e of g.effects)e.life-=dt;g.effects=g.effects.filter(e=>e.life>0);for(const n of g.numbers){n.life-=dt;n.y-=dt*28}g.numbers=g.numbers.filter(n=>n.life>0);if(g.health<=0){g.health=0;g.status='dead'}else checkLevel(g);
}
